const fmt = (d) => { if (!d) return ''; const t = new Date(d); return isNaN(t) ? String(d) : t.toLocaleDateString('es-PE', { timeZone: 'America/Lima' }); };
return $input.all().map(({ json }) => {
  const esHoy = Number(json.dias_restantes) === 0;
  const clave = esHoy ? 'recordatorio_hoy' : 'recordatorio_3d';
  const cuerpo = (esHoy ? json.t_hoy : json.t_3d) || 'Hola {{nombres}}, tu plan vence el {{fecha_fin}} ({{dias_restantes}} dias). Renueva a tiempo.';
  const vars = {
    nombres: json.nombres || '', apellidos: json.apellidos || '',
    plan: json.plan_nombre || '', fecha_fin: fmt(json.fecha_fin),
    dias_restantes: json.dias_restantes ?? '', monto: ''
  };
  const texto = String(cuerpo).replace(/\{\{\s*(\w+)\s*\}\}/g, (_, k) => (vars[k] ?? ''));
  let numero = String(json.telefono || '').replace(/\D/g, '');
  if (numero.length === 9) numero = '51' + numero;
  return { json: { socio_id: json.socio_id, suscripcion_id: json.suscripcion_id, clave, numero, texto } };
}).filter((i) => i.json.numero);

const esc = (s) => String(s ?? '').replace(/'/g, "''");
return $('Render').all().map(({ json: r }) => {
  const sql = `INSERT INTO mensajes_enviados (socio_id, telefono, canal, plantilla_clave, contenido, estado, enviado_en, referencia_tipo, referencia_id) VALUES ('${esc(r.socio_id)}', '${esc(r.numero)}', 'whatsapp', '${esc(r.clave)}', '${esc(r.texto)}', 'enviado', now(), 'suscripcion', ${r.suscripcion_id ? `'${esc(r.suscripcion_id)}'` : 'NULL'})`;
  return { json: { sql } };
});
